//! Read the backing text of a Messages NSAttributedString archive.
//!
//! This is a data reader, not an Objective-C unarchiver: attribute objects are walked
//! only to keep the stream's references in sync, and never instantiated. It retains
//! just shared strings, class kinds and extracted text, not a general object graph.
//! The wire-format facts are described at
//! <https://chrissardegna.com/blog/reverse-engineering-apples-typedstream-format/>.
//! Tests use our own samples, including archives generated by Apple's NSArchiver.

const NEW: u8 = 0x84;
const NIL: u8 = 0x85;
const END: u8 = 0x86;
const MAX_DEPTH: usize = 64;
const MAX_REFERENCES: usize = 100_000;

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    String,
    Attributed,
    Other,
}

#[derive(Clone, Copy)]
struct Object<'a> {
    kind: Kind,
    text: Option<&'a str>,
}

#[derive(Clone, Copy)]
enum Value<'a> {
    Bytes(&'a str),
    Object(Object<'a>),
    Other,
}

#[derive(Clone, Copy)]
enum Reference<'a> {
    Pending,
    Class(Kind),
    Object(Object<'a>),
    CString,
}

struct Reader<'a> {
    rest: &'a [u8],
    little_endian: bool,
    strings: Vec<&'a [u8]>,
    references: Vec<Reference<'a>>,
    work: usize,
}

/// Unsupported or malformed archives have no decoded text. A valid empty string is
/// `Some("")`, so callers can distinguish it from a decoding failure.
pub fn text(data: &[u8]) -> Option<&str> {
    let mut reader = Reader {
        rest: data,
        little_endian: true,
        strings: Vec::new(),
        references: Vec::new(),
        // Also bound work on zero-sized aggregate types and deeply shared data.
        work: data.len().saturating_mul(4).clamp(128, 4_000_000),
    };
    if reader.byte()? != 4 || reader.byte()? != 11 {
        return None;
    }
    reader.little_endian = match reader.take(11)? {
        b"streamtyped" => true,
        b"typedstream" => false,
        _ => return None,
    };
    if reader.integer(false)? != 1000 || reader.shared()? != b"@" {
        return None;
    }
    let Value::Object(object) = reader.object(0)? else {
        return None;
    };
    if object.kind != Kind::Attributed || !reader.rest.is_empty() {
        return None;
    }
    object.text
}

impl<'a> Reader<'a> {
    fn spend(&mut self) -> Option<()> {
        self.work = self.work.checked_sub(1)?;
        Some(())
    }

    fn take(&mut self, count: usize) -> Option<&'a [u8]> {
        let (value, rest) = self.rest.split_at_checked(count)?;
        self.rest = rest;
        Some(value)
    }

    fn byte(&mut self) -> Option<u8> {
        Some(self.take(1)?[0])
    }

    // The integer's tag determines its width, independently of the field's ObjC
    // type. Signedness comes from that field (references are signed integers).
    fn integer(&mut self, signed: bool) -> Option<i128> {
        let tag = self.byte()?;
        let width = match tag {
            0x81 => 2,
            0x82 => 4,
            0x87 => 8,
            0x80..=0x91 => return None,
            _ => {
                return Some(if signed {
                    tag as i8 as i128
                } else {
                    tag as i128
                });
            }
        };
        let bytes = self.take(width)?;
        let mut value = 0u64;
        for i in 0..width {
            let byte = bytes[if self.little_endian { width - 1 - i } else { i }];
            value = (value << 8) | u64::from(byte);
        }
        let value = i128::from(value);
        Some(if signed && value & (1 << (width * 8 - 1)) != 0 {
            value - (1i128 << (width * 8))
        } else {
            value
        })
    }

    fn index(&mut self) -> Option<usize> {
        // Reference zero is encoded as -110 (0x92); wide references use the same
        // signed integer encoding rather than wrapping back to a single byte.
        usize::try_from(self.integer(true)? + 110).ok()
    }

    fn shared(&mut self) -> Option<&'a [u8]> {
        self.spend()?;
        if *self.rest.first()? == NEW {
            self.byte()?;
            let count = usize::try_from(self.integer(false)?).ok()?;
            let value = self.take(count)?;
            if self.strings.len() >= MAX_REFERENCES {
                return None;
            }
            self.strings.push(value);
            Some(value)
        } else {
            let index = self.index()?;
            self.strings.get(index).copied()
        }
    }

    fn reserve(&mut self) -> Option<usize> {
        if self.references.len() >= MAX_REFERENCES {
            return None;
        }
        let index = self.references.len();
        self.references.push(Reference::Pending);
        Some(index)
    }

    fn class(&mut self, depth: usize) -> Option<Kind> {
        self.spend()?;
        if depth >= MAX_DEPTH {
            return None;
        }
        match *self.rest.first()? {
            NIL => {
                self.byte()?;
                Some(Kind::Other)
            }
            NEW => {
                self.byte()?;
                let name = self.shared()?;
                self.integer(true)?; // class version
                let index = self.reserve()?;
                let parent = self.class(depth + 1)?;
                let kind = match name {
                    b"NSString" | b"NSMutableString" => Kind::String,
                    b"NSAttributedString" | b"NSMutableAttributedString" => Kind::Attributed,
                    _ => parent,
                };
                self.references[index] = Reference::Class(kind);
                Some(kind)
            }
            _ => {
                let index = self.index()?;
                match self.references.get(index)? {
                    Reference::Class(kind) => Some(*kind),
                    _ => None,
                }
            }
        }
    }

    fn object(&mut self, depth: usize) -> Option<Value<'a>> {
        self.spend()?;
        if depth >= MAX_DEPTH {
            return None;
        }
        match *self.rest.first()? {
            NIL => {
                self.byte()?;
                Some(Value::Other)
            }
            NEW => {
                self.byte()?;
                let index = self.reserve()?;
                // A new object must have an actual class, not a nil class chain.
                if *self.rest.first()? == NIL {
                    return None;
                }
                let kind = self.class(depth + 1)?;
                let mut object = Object { kind, text: None };
                let mut first_group = true;
                while *self.rest.first()? != END {
                    let types = self.shared()?;
                    if types.is_empty() {
                        return None;
                    }
                    let mut encoding = types;
                    let first = self.value(&mut encoding, depth + 1)?;
                    if object.text.is_none() {
                        object.text = match (kind, first) {
                            (Kind::String, Value::Bytes(text)) if first_group => Some(text),
                            (Kind::Attributed, Value::Object(child))
                                if child.kind == Kind::String =>
                            {
                                child.text
                            }
                            _ => None,
                        };
                    }
                    while !encoding.is_empty() {
                        self.value(&mut encoding, depth + 1)?;
                    }
                    first_group = false;
                }
                self.byte()?;
                self.references[index] = Reference::Object(object);
                Some(Value::Object(object))
            }
            _ => {
                let index = self.index()?;
                match self.references.get(index)? {
                    Reference::Object(object) => Some(Value::Object(*object)),
                    // Cycles cannot supply backing text; they need no traversal.
                    Reference::Pending => Some(Value::Other),
                    _ => None,
                }
            }
        }
    }

    fn value(&mut self, encoding: &mut &[u8], depth: usize) -> Option<Value<'a>> {
        self.spend()?;
        if depth >= MAX_DEPTH {
            return None;
        }
        let (&tag, rest) = encoding.split_first()?;
        *encoding = rest;
        match tag {
            b'@' => return self.object(depth),
            b'+' => {
                let count = usize::try_from(self.integer(false)?).ok()?;
                return Some(Value::Bytes(std::str::from_utf8(self.take(count)?).ok()?));
            }
            b'c' | b'C' | b'B' => {
                self.byte()?;
            }
            b's' | b'i' | b'l' | b'q' => {
                self.integer(true)?;
            }
            b'S' | b'I' | b'L' | b'Q' => {
                self.integer(false)?;
            }
            b'f' | b'd' => {
                if *self.rest.first()? == 0x83 {
                    self.byte()?;
                    self.take(if tag == b'f' { 4 } else { 8 })?;
                } else {
                    self.integer(true)?;
                }
            }
            b'*' => match *self.rest.first()? {
                NIL => {
                    self.byte()?;
                }
                NEW => {
                    self.byte()?;
                    let index = self.reserve()?;
                    self.shared()?;
                    self.references[index] = Reference::CString;
                }
                _ => {
                    let index = self.index()?;
                    if !matches!(self.references.get(index)?, Reference::CString) {
                        return None;
                    }
                }
            },
            b':' | b'%' => {
                if *self.rest.first()? == NIL {
                    self.byte()?;
                } else {
                    self.shared()?;
                }
            }
            b'#' => {
                self.class(depth + 1)?;
            }
            b'[' => {
                let digits = encoding.iter().take_while(|b| b.is_ascii_digit()).count();
                let count: usize = std::str::from_utf8(encoding.get(..digits)?)
                    .ok()?
                    .parse()
                    .ok()?;
                *encoding = &encoding[digits..];
                let element = *encoding;
                // Byte arrays are stored raw, including bytes that resemble tags.
                if element.starts_with(b"c]") || element.starts_with(b"C]") {
                    self.take(count)?;
                    *encoding = &element[2..];
                } else {
                    if count > self.work {
                        return None;
                    }
                    // Messages uses byte arrays. Empty arrays of other types
                    // are outside the supported subset.
                    if count == 0 {
                        return None;
                    }
                    let mut end = element;
                    for _ in 0..count {
                        end = element;
                        self.value(&mut end, depth + 1)?;
                    }
                    *encoding = end.strip_prefix(b"]")?;
                }
            }
            b'{' => {
                let equals = encoding.iter().position(|b| *b == b'=')?;
                if encoding[..equals]
                    .iter()
                    .any(|b| matches!(b, b'{' | b'}' | b'[' | b']'))
                {
                    return None;
                }
                *encoding = &encoding[equals + 1..];
                while !encoding.starts_with(b"}") {
                    self.value(encoding, depth + 1)?;
                }
                *encoding = &encoding[1..];
            }
            _ => return None,
        }
        Some(Value::Other)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // Assemble a minimal archive from wire-format facts. Compatibility coverage
    // comes separately from Apple's encoder, not from this little test helper.
    fn sample(body: &[u8], metadata: &[u8]) -> Vec<u8> {
        fn shared(out: &mut Vec<u8>, bytes: &[u8]) {
            out.extend([NEW, bytes.len() as u8]);
            out.extend(bytes);
        }
        let mut out = b"\x04\x0bstreamtyped\x81\xe8\x03".to_vec();
        shared(&mut out, b"@");
        out.extend([NEW, NEW]); // object 0, class 1
        shared(&mut out, b"NSAttributedString");
        out.extend([0, NEW]);
        shared(&mut out, b"NSObject"); // class 2
        out.extend([0, NIL, 0x92, NEW, NEW]); // @, object 3, class 4
        shared(&mut out, b"NSString");
        out.extend([1, 0x94]); // version 1, cached NSObject class
        shared(&mut out, b"+");
        match body.len() {
            0..=127 => out.push(body.len() as u8),
            128..=65535 => {
                out.push(0x81);
                out.extend((body.len() as u16).to_le_bytes());
            }
            _ => {
                out.push(0x82);
                out.extend((body.len() as u32).to_le_bytes());
            }
        }
        out.extend(body);
        out.push(END);
        out.extend(metadata);
        out.push(END);
        out
    }

    #[test]
    fn backing_text_is_exact_including_empty_unicode_nul_and_long_strings() {
        for body in [
            "".to_owned(),
            "hello 👋\n日本語\0end".to_owned(),
            "é".repeat(40_000),
        ] {
            assert_eq!(text(&sample(body.as_bytes(), &[])), Some(body.as_str()));
        }
    }

    #[test]
    fn validates_metadata_instead_of_scanning_for_printable_text() {
        // An attribute byte array containing strings and format markers is not
        // another object, and its contents must not be interpreted as one.
        let mut suffix = b"\x84\x04[5c]".to_vec();
        suffix.extend([NEW, NIL, END, b'x', 0]);
        assert_eq!(text(&sample(b"The body", &suffix)), Some("The body"));
        assert_eq!(text(&sample(b"The body", b"\x84\x01^")), None);
        assert_eq!(text(&sample(b"The body", b"\x84\x01@\xff")), None);
        // Index zero denotes an object; it cannot be used as a class reference.
        assert_eq!(text(&sample(b"The body", b"\x92\x84\x92\x86")), None);
    }

    #[test]
    fn cstrings_take_reference_slots_even_when_their_text_is_shared() {
        // New C string pointer, then another pointer to the same shared text,
        // then references to both. They occupy distinct object table slots 5/6.
        let suffix = b"\x84\x01*\x84\x84\x01i\x97\x84\x98\x97\x97\x97\x98";
        assert_eq!(text(&sample(b"Numbers", suffix)), Some("Numbers"));
        let mut broken = suffix.to_vec();
        *broken.last_mut().unwrap() = 0x96; // class 4, not a C string
        assert_eq!(text(&sample(b"Numbers", &broken)), None);
    }

    #[test]
    fn rejects_truncation_invalid_utf8_headers_and_trailing_data() {
        let archive = sample(b"complete message", &[]);
        for end in 0..archive.len() {
            assert_eq!(text(&archive[..end]), None, "cut at {end}");
        }
        assert_eq!(text(&sample(b"invalid \xff text", &[])), None);
        let mut bad_header = archive.clone();
        bad_header[0] = 3;
        assert_eq!(text(&bad_header), None);
        let mut extra = archive;
        extra.push(0);
        assert_eq!(text(&extra), None);
    }

    #[test]
    fn rejects_huge_lengths_and_excessive_recursion_without_allocating_them() {
        // No element data follows this hostile array count.
        assert_eq!(text(&sample(b"body", b"\x84\x0c[999999999@]")), None);
        let mut nested = Vec::new();
        for _ in 0..100 {
            // Each object reuses NSString's class; its field is another object.
            nested.extend([0x92, NEW, 0x96]);
        }
        nested.extend([END; 100]);
        assert_eq!(text(&sample(b"body", &nested)), None);
        let mut archive = sample(b"x", &[]);
        let length = archive.len() - 3;
        archive.splice(
            length..length + 1,
            [0x87, 255, 255, 255, 255, 255, 255, 255, 255],
        );
        assert_eq!(text(&archive), None);
    }

    #[test]
    fn malformed_inputs_do_not_panic() {
        let archive = sample(b"body", &[]);
        for index in 0..archive.len() {
            for byte in 0..=255 {
                let mut changed = archive.clone();
                changed[index] = byte;
                let _ = text(&changed);
            }
        }
        let mut state = 0x1234_5678u32;
        for length in 0..512 {
            let data: Vec<u8> = (0..length)
                .map(|_| {
                    state ^= state << 13;
                    state ^= state >> 17;
                    state ^= state << 5;
                    state as u8
                })
                .collect();
            let _ = text(&data);
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn matches_apple_archives() {
        // Swift must write its module cache where a sandboxed test can write.
        let cache = std::env::temp_dir().join(format!("msgmcp-swift-cache-{}", std::process::id()));
        let generated = std::process::Command::new("swift")
            .arg("-module-cache-path")
            .arg(cache)
            .arg(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/scripts/fixtures/attributed_body.swift"
            ))
            .output()
            .expect("run Apple's synthetic archive generator");
        assert!(
            generated.status.success(),
            "{}",
            String::from_utf8_lossy(&generated.stderr)
        );
        let samples: serde_json::Value = serde_json::from_slice(&generated.stdout).unwrap();
        for sample in samples.as_array().unwrap() {
            let hex = sample["hex"].as_str().unwrap();
            let bytes: Vec<u8> = (0..hex.len())
                .step_by(2)
                .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
                .collect();
            assert_eq!(text(&bytes), sample["text"].as_str(), "{}", sample["name"]);
            for cut in [0, 15, bytes.len() / 2, bytes.len() - 1] {
                assert_eq!(
                    text(&bytes[..cut]),
                    None,
                    "{} truncated at {cut}",
                    sample["name"]
                );
            }
        }
    }
}
